// Strict allowlist for the xb.member.pos_exceptions.v1 event from the monthly in-store member
// discount check on the AutoCount server (#268). Anything outside the closed contract is rejected
// with a fixed reason code (HTTP 400 to the VM); nothing unvalidated reaches the email. Request
// headers are never read or passed on. The event carries counts, closed codes, receipt numbers,
// outlet codes, days, rates and member numbers masked to the last 3 characters only: no name,
// phone, email, full member number or amount. The call node pins system MEMBER-POS.
const items = $input.all();
const reject = (reason) => [{ json: { valid: false, reason } }];
if (items.length !== 1) return reject('POS_XR_ITEM_COUNT');
const body = items[0].json && items[0].json.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) return reject('POS_XR_BODY');

const KEYS = ['schema', 'event', 'run_id', 'month', 'status', 'failure_class', 'counts', 'outlets', 'rows', 'rows_not_listed', 'stale_outlets'];
const COUNT_KEYS = ['receipts_read', 'cancelled', 'not_positive', 'member_rate', 'guest', 'expired', 'same_receipt', 'member_valid', 'no_member_on_receipt', 'member_not_found', 'type_other', 'changed_after_sale', 'member_inactive'];
const OUTLET_KEYS = ['outlet', 'guest', 'expired', 'same_receipt', 'no_member_on_receipt'];
const ROW_KEYS = ['doc_no', 'outlet', 'day', 'rate', 'reason', 'member', 'record_note'];
const REASONS = ['guest', 'expired', 'same_receipt'];
const RECORD_NOTES = ['none', 'created_on_sale_day', 'edited_on_or_after_sale_day'];
const FAILURE_CLASSES = ['config_invalid', 'timezone_unavailable', 'identity_refused', 'credential_unavailable', 'lock_timeout', 'source_error', 'write_failed', 'internal_error'];
const MAX_ROWS = 12;
const MAX_OUTLETS = 10;
const OUTLET_RE = /^[A-Za-z0-9_-]{1,12}$/;
const DOC_RE = /^[A-Za-z0-9\/_.-]{1,30}$/;
const DAY_RE = /^\d{4}-\d\d-\d\d$/;
const RATE_RE = /^\d{1,2}(\.\d{1,2})?%$/;
const MEMBER_RE = /^\*\*\*[A-Za-z0-9?]{1,3}$/;
const sameKeys = (obj, keys) => obj && typeof obj === 'object' && !Array.isArray(obj)
  && Object.keys(obj).length === keys.length && keys.every((key) => Object.prototype.hasOwnProperty.call(obj, key));
const isCount = (value) => Number.isInteger(value) && value >= 0 && value <= 1000000;

if (!sameKeys(body, KEYS)) return reject('POS_XR_KEYS');
if (body.schema !== 'xb.member.pos_exceptions.v1') return reject('POS_XR_SCHEMA');
if (body.event !== 'member_pos_exceptions') return reject('POS_XR_EVENT');
if (typeof body.run_id !== 'string' || !/^([0-9a-f]{32}|unknown)$/.test(body.run_id)) return reject('POS_XR_RUN_ID');
if (typeof body.month !== 'string' || !/^20\d\d-(0[1-9]|1[0-2])$/.test(body.month)) return reject('POS_XR_MONTH');
const status = body.status;
if (!['report', 'pos_sync_stale', 'failed'].includes(status)) return reject('POS_XR_STATUS');
const report = status === 'report';
if (status === 'failed' ? !FAILURE_CLASSES.includes(body.failure_class) : body.failure_class !== null) return reject('POS_XR_FAILURE_CLASS');
if (!Array.isArray(body.stale_outlets) || body.stale_outlets.length > MAX_OUTLETS) return reject('POS_XR_STALE_OUTLETS');
if (!body.stale_outlets.every((code) => typeof code === 'string' && OUTLET_RE.test(code))) return reject('POS_XR_STALE_OUTLETS');
if ((status === 'pos_sync_stale') !== (body.stale_outlets.length > 0)) return reject('POS_XR_STALE_OUTLETS');
if (!Array.isArray(body.outlets) || !Array.isArray(body.rows) || !isCount(body.rows_not_listed)) return reject('POS_XR_LIST');
if (!report) {
  if (body.counts !== null || body.outlets.length || body.rows.length || body.rows_not_listed) return reject('POS_XR_LIST');
} else {
  if (!sameKeys(body.counts, COUNT_KEYS) || !COUNT_KEYS.every((key) => isCount(body.counts[key]))) return reject('POS_XR_COUNTS');
  if (body.outlets.length > MAX_OUTLETS || !body.outlets.every((o) => sameKeys(o, OUTLET_KEYS) && typeof o.outlet === 'string'
    && OUTLET_RE.test(o.outlet) && OUTLET_KEYS.slice(1).every((key) => isCount(o[key])))) return reject('POS_XR_OUTLETS');
  if (body.rows.length > MAX_ROWS || !body.rows.every((r) => sameKeys(r, ROW_KEYS) && typeof r.doc_no === 'string' && DOC_RE.test(r.doc_no)
    && typeof r.outlet === 'string' && OUTLET_RE.test(r.outlet) && typeof r.day === 'string' && DAY_RE.test(r.day)
    && r.day.slice(0, 7) === body.month && typeof r.rate === 'string' && RATE_RE.test(r.rate) && REASONS.includes(r.reason)
    && typeof r.member === 'string' && MEMBER_RE.test(r.member) && RECORD_NOTES.includes(r.record_note)
    && (r.record_note === 'none' || r.reason === 'guest'))) return reject('POS_XR_ROWS');
}

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const monthLabel = MONTHS[Number(body.month.slice(5)) - 1] + ' ' + body.month.slice(0, 4);
const run = 'Run: ' + body.run_id.slice(0, 8) + '. Runbook: docs/autocount2-automation/member_pos_exceptions_runbook.md';
let severity;
let key;
let short;
let lines;
if (report) {
  const c = body.counts;
  const total = c.guest + c.expired + c.same_receipt;
  // The VM emails only when there is something to act on; a report without exceptions is a contract break.
  if (total === 0 || body.rows.length + body.rows_not_listed !== total) return reject('POS_XR_COUNTS');
  const LABELS = { guest: 'registered, not qualified', expired: 'membership had expired', same_receipt: 'may be the receipt that made them a member' };
  // The check knows only when the member record was created or last edited, never that its type changed.
  const NOTES = { none: '', created_on_sale_day: ' | member record created on the sale day',
    edited_on_or_after_sale_day: ' | member record edited on or after the sale day (check its history)' };
  severity = 'WARN';
  key = 'exceptions:' + body.month;
  short = 'exceptions_' + body.month;
  lines = [
    'In-store member discounts, ' + monthLabel + ': ' + total + ' receipt(s) to check',
    '',
    'The member rate was keyed on the receipt, but the member record does not qualify:',
    '- Registered, not qualified (GUEST): ' + c.guest,
    '- Membership had expired: ' + c.expired,
    '- May be on the receipt that made them a member (the rate starts from the next purchase): ' + c.same_receipt,
    '',
    'Receipts (look each one up by its number in AutoCount):',
    ...body.rows.map((r) => '- ' + r.doc_no + ' | ' + r.outlet + ' | ' + r.day + ' | ' + r.rate + ' | ' + LABELS[r.reason]
      + ' | member ' + r.member + NOTES[r.record_note]),
    ...(body.rows_not_listed ? ['- (+' + body.rows_not_listed + ' more, not listed: see the run record on the AutoCount server)'] : []),
    '',
    'By outlet (registered / expired / same receipt / rate with no member on the receipt): '
      + (body.outlets.length ? body.outlets.map((o) => o.outlet + ' ' + o.guest + '/' + o.expired + '/' + o.same_receipt + '/' + o.no_member_on_receipt).join('; ') : 'none'),
    'Also counted, not exceptions: rate with no member on the receipt ' + c.no_member_on_receipt + '; member number not found '
      + c.member_not_found + '; other member types ' + c.type_other + '.',
    'Read ' + c.receipts_read + ' receipts (' + c.cancelled + ' cancelled and ' + c.not_positive + ' returns or zero receipts skipped); '
      + c.member_rate + ' had the member rate.',
    'Next: the shop manager checks each receipt and coaches the outlet. "Same receipt" rows need nothing undone.',
    run,
  ];
} else if (status === 'pos_sync_stale') {
  severity = 'WARN';
  key = 'pos_sync_stale:' + body.month;
  short = 'pos_sync_stale_' + body.month;
  lines = [
    'In-store member discount check for ' + monthLabel + ' is waiting: the till data is not fully synced.',
    'Outlets with no finished POS sync since the month ended: ' + body.stale_outlets.join(', '),
    'Nothing is reported until every outlet has synced. The task tries again every day; this email is sent once a month.',
    'Next: check that the till PC at each outlet above is on and its AutoCount POS sync runs. Still waiting after 3 days: forward to Claude.',
    run,
  ];
} else {
  severity = 'ERROR';
  key = 'run_failed:' + body.failure_class;
  short = 'run_failed:' + body.failure_class;
  lines = [
    'In-store member discount check for ' + monthLabel + ' FAILED: ' + body.failure_class,
    'Nothing was reported. The task tries again every day; this email is sent once per month and failure.',
    'Next: forward to Claude.',
    run,
  ];
}
return [{ json: { valid: true, severity, key, short, lines } }];
